# -*- coding: utf-8 -*-# qt_runner.pyimport osimport sysimport timeimport sqlite3import tracebackfrom pathlib import Pathfrom PyQt5 import QtWidgets, QtCore, QtGuiAPP_NAME = "SenseiTrader Runner"ORG_NAME = "SenseiTrader"SETTINGS_APP = "qt_runner"def app_dir() -> Path:    return Path(__file__).resolve().parentdef logs_dir() -> Path:    p = app_dir() / "logs"    p.mkdir(parents=True, exist_ok=True)    return pdef write_text_safe(path: Path, text: str) -> None:    path.parent.mkdir(parents=True, exist_ok=True)    path.write_text(text, encoding="utf-8", errors="replace")def qprocess_err_name(err: QtCore.QProcess.ProcessError) -> str:    m = {        QtCore.QProcess.FailedToStart: "FailedToStart",        QtCore.QProcess.Crashed: "Crashed",        QtCore.QProcess.Timedout: "Timedout",        QtCore.QProcess.WriteError: "WriteError",        QtCore.QProcess.ReadError: "ReadError",        QtCore.QProcess.UnknownError: "UnknownError",    }    return m.get(err, str(int(err)))class RunnerWindow(QtWidgets.QMainWindow):    def __init__(self):        super().__init__()        self.APP_DIR = app_dir()        self.LOGS_DIR = logs_dir()        self.BOOT_LOG = self.LOGS_DIR / "qt_runner_boot.txt"        self.CRASH_LOG = self.LOGS_DIR / "qt_runner_crash.txt"        self.GUI_LOG = self.LOGS_DIR / "qt_runner_gui.log"        self.EXIT_LOG = self.LOGS_DIR / "qt_runner_exit.txt"        self.settings = QtCore.QSettings(ORG_NAME, SETTINGS_APP)        self.proc = QtCore.QProcess(self)        self.proc.setProcessChannelMode(QtCore.QProcess.MergedChannels)        self.proc.readyReadStandardOutput.connect(self.on_ready_read)        self.proc.started.connect(self.on_proc_started)        self.proc.finished.connect(self.on_proc_finished)        self.proc.errorOccurred.connect(self.on_proc_error)        self._stop_timer = QtCore.QTimer(self)        self._stop_timer.setSingleShot(True)        self._stop_timer.timeout.connect(self.force_kill)        self._heartbeat_timer = QtCore.QTimer(self)        self._heartbeat_timer.setInterval(2000)        self._heartbeat_timer.timeout.connect(self.poll_heartbeat)        self._stopping = False        self._exit_requested = False  # ВЫХОД ТОЛЬКО ПО ЯВНОЙ КОМАНДЕ "Exit"        self._build_ui()        self._setup_tray()        self._write_boot()        self.append_log("[runner] GUI ready.")        self.gui_log("[runner] GUI ready.")        QtCore.QTimer.singleShot(0, self._bring_to_front)    # ---------------- UI ----------------    def _build_ui(self):        self.setWindowTitle(APP_NAME)        self.resize(1000, 650)        central = QtWidgets.QWidget()        self.setCentralWidget(central)        root = QtWidgets.QVBoxLayout(central)        root.setContentsMargins(10, 10, 10, 10)        root.setSpacing(8)        cfg_row = QtWidgets.QHBoxLayout()        root.addLayout(cfg_row)        cfg_row.addWidget(QtWidgets.QLabel("Config (.toml):"))        self.cfg_edit = QtWidgets.QLineEdit()        self.cfg_edit.setPlaceholderText("Path to config file")        cfg_row.addWidget(self.cfg_edit, 1)        btn_pick = QtWidgets.QPushButton("Browse...")        btn_pick.clicked.connect(self.pick_config)        cfg_row.addWidget(btn_pick)        btn_open_cfg = QtWidgets.QPushButton("Open config folder")        btn_open_cfg.clicked.connect(            lambda: self.open_in_explorer(                (self.cfg_path().parent if self.cfg_path().exists() else (self.APP_DIR / "config"))            )        )        cfg_row.addWidget(btn_open_cfg)        env_box = QtWidgets.QGroupBox("Environment for child process (optional)")        root.addWidget(env_box)        env_layout = QtWidgets.QGridLayout(env_box)        env_layout.setColumnStretch(1, 1)        self.mode_combo = QtWidgets.QComboBox()        self.mode_combo.addItems(["offline", "paper", "live"])        env_layout.addWidget(QtWidgets.QLabel("SENSEI_MODE"), 0, 0)        env_layout.addWidget(self.mode_combo, 0, 1)        self.db_edit = QtWidgets.QLineEdit()        self.db_edit.setPlaceholderText(r"data\trader_paper.db (or full path)")        env_layout.addWidget(QtWidgets.QLabel("SENSEI_DB_PATH"), 1, 0)        env_layout.addWidget(self.db_edit, 1, 1)        self.signals_enable = QtWidgets.QCheckBox("Enable signals (SENSEI_SIGNALS_ENABLE=1)")        self.signals_enable.setChecked(True)        env_layout.addWidget(self.signals_enable, 2, 0, 1, 2)        self.signals_path = QtWidgets.QLineEdit()        self.signals_path.setPlaceholderText(r"signals")        env_layout.addWidget(QtWidgets.QLabel("SENSEI_SIGNALS_PATH"), 3, 0)        env_layout.addWidget(self.signals_path, 3, 1)        self.ib_sync_enable = QtWidgets.QCheckBox("Enable IB fills sync (SENSEI_IB_SYNC_ENABLE=1)")        self.ib_sync_enable.setChecked(False)        env_layout.addWidget(self.ib_sync_enable, 4, 0, 1, 2)        self.ib_sync_interval = QtWidgets.QSpinBox()        self.ib_sync_interval.setRange(1, 3600)        self.ib_sync_interval.setValue(10)        env_layout.addWidget(QtWidgets.QLabel("SENSEI_IB_SYNC_INTERVAL_SECONDS"), 5, 0)        env_layout.addWidget(self.ib_sync_interval, 5, 1)        self.ib_sync_lookback = QtWidgets.QSpinBox()        self.ib_sync_lookback.setRange(1, 10080)        self.ib_sync_lookback.setValue(240)        env_layout.addWidget(QtWidgets.QLabel("SENSEI_IB_SYNC_LOOKBACK_MINUTES"), 6, 0)        env_layout.addWidget(self.ib_sync_lookback, 6, 1)        btn_row = QtWidgets.QHBoxLayout()        root.addLayout(btn_row)        self.btn_start = QtWidgets.QPushButton("Start service")        self.btn_start.clicked.connect(self.start_service)        btn_row.addWidget(self.btn_start)        self.btn_stop = QtWidgets.QPushButton("Stop service")        self.btn_stop.clicked.connect(self.stop_service)        self.btn_stop.setEnabled(False)        btn_row.addWidget(self.btn_stop)        btn_row.addSpacing(20)        btn_open_logs = QtWidgets.QPushButton("Open logs folder")        btn_open_logs.clicked.connect(lambda: self.open_in_explorer(self.LOGS_DIR))        btn_row.addWidget(btn_open_logs)        btn_open_signals = QtWidgets.QPushButton("Open signals folder")        btn_open_signals.clicked.connect(lambda: self.open_in_explorer(self.APP_DIR / "signals"))        btn_row.addWidget(btn_open_signals)        btn_clear = QtWidgets.QPushButton("Clear view")        btn_clear.clicked.connect(lambda: self.log_view.clear())        btn_row.addWidget(btn_clear)        btn_row.addStretch(1)        self.status_lbl = QtWidgets.QLabel("Status: idle")        self.status_lbl.setStyleSheet("font-weight: bold;")        root.addWidget(self.status_lbl)        self.log_view = QtWidgets.QPlainTextEdit()        self.log_view.setReadOnly(True)        self.log_view.setFont(QtGui.QFont("Consolas", 10))        root.addWidget(self.log_view, 1)        default_cfg = self.APP_DIR / "config" / "app_offline.toml"        self.cfg_edit.setText(str(self.settings.value("cfg_path", str(default_cfg))))        self.mode_combo.setCurrentText(str(self.settings.value("mode", "offline")))        self.db_edit.setText(str(self.settings.value("db_path", "")))        self.signals_enable.setChecked(self.settings.value("signals_enable", True, type=bool))        self.signals_path.setText(str(self.settings.value("signals_path", "signals")))        self.ib_sync_enable.setChecked(self.settings.value("ib_sync_enable", False, type=bool))        self.ib_sync_interval.setValue(int(self.settings.value("ib_sync_interval", 10)))        self.ib_sync_lookback.setValue(int(self.settings.value("ib_sync_lookback", 240)))    def _setup_tray(self):        # Трей обязателен: закрытие окна -> hide (иначе lastWindowClosed завершит app)        self.tray = QtWidgets.QSystemTrayIcon(self)        # Простейшая иконка (стандартная), чтобы не зависеть от файлов.        icon = self.style().standardIcon(QtWidgets.QStyle.SP_ComputerIcon)        self.tray.setIcon(icon)        self.tray.setToolTip(APP_NAME)        menu = QtWidgets.QMenu()        act_show = menu.addAction("Show")        act_show.triggered.connect(self._tray_show)        act_hide = menu.addAction("Hide")        act_hide.triggered.connect(self._tray_hide)        menu.addSeparator()        act_start = menu.addAction("Start service")        act_start.triggered.connect(self.start_service)        act_stop = menu.addAction("Stop service")        act_stop.triggered.connect(self.stop_service)        menu.addSeparator()        act_exit = menu.addAction("Exit")        act_exit.triggered.connect(self.request_exit)        self.tray.setContextMenu(menu)        self.tray.activated.connect(self._on_tray_activated)        self.tray.show()    def _on_tray_activated(self, reason: QtWidgets.QSystemTrayIcon.ActivationReason):        if reason in (QtWidgets.QSystemTrayIcon.Trigger, QtWidgets.QSystemTrayIcon.DoubleClick):            if self.isVisible():                self._tray_hide()            else:                self._tray_show()    def _tray_show(self):        self.showNormal()        self.raise_()        self.activateWindow()        self.gui_log("[tray] show")    def _tray_hide(self):        self.hide()        self.gui_log("[tray] hide")    def request_exit(self):        # Единственный “правильный” выход из приложения        self._exit_requested = True        self.gui_log("[gui] exit requested")        self.close()    def _bring_to_front(self):        self.show()        self.raise_()        self.activateWindow()    # ---------------- Boot/Crash logs ----------------    def _write_boot(self):        lines = []        lines.append("=" * 70)        lines.append(f"ts_local       = {time.strftime('%Y-%m-%d %H:%M:%S')}")        lines.append(f"sys.executable = {sys.executable}")        lines.append(f"cwd            = {os.getcwd()}")        lines.append(f"APP_DIR        = {str(self.APP_DIR)}")        lines.append(f"DEFAULT_CONFIG = {str(self.cfg_path())}")        lines.append("PyQt5 import   = OK")        lines.append("Creating QApplication... OK")        lines.append("Creating main window... OK")        lines.append("Entering event loop (app.exec_) ...")        write_text_safe(self.BOOT_LOG, "\n".join(lines) + "\n")    def _write_crash(self, err_text: str):        write_text_safe(self.CRASH_LOG, err_text)    def gui_log(self, msg: str):        ts = time.strftime("%Y-%m-%d %H:%M:%S")        line = f"[{ts}] {msg}"        try:            with self.GUI_LOG.open("a", encoding="utf-8", errors="replace") as f:                f.write(line + "\n")        except Exception:            pass    # ---------------- Helpers ----------------    def cfg_path(self) -> Path:        return Path(self.cfg_edit.text().strip()).expanduser()    def open_in_explorer(self, p: Path):        p = Path(p)        try:            if not p.exists():                p.mkdir(parents=True, exist_ok=True)            QtGui.QDesktopServices.openUrl(QtCore.QUrl.fromLocalFile(str(p)))        except Exception as e:            self.append_log(f"[gui] open explorer error: {e}")    def append_log(self, text: str):        self.log_view.appendPlainText(text)        self.log_view.verticalScrollBar().setValue(self.log_view.verticalScrollBar().maximum())    def set_status(self, text: str):        self.status_lbl.setText(f"Status: {text}")    def persist_settings(self):        self.settings.setValue("cfg_path", str(self.cfg_path()))        self.settings.setValue("mode", self.mode_combo.currentText())        self.settings.setValue("db_path", self.db_edit.text().strip())        self.settings.setValue("signals_enable", self.signals_enable.isChecked())        self.settings.setValue("signals_path", self.signals_path.text().strip())        self.settings.setValue("ib_sync_enable", self.ib_sync_enable.isChecked())        self.settings.setValue("ib_sync_interval", self.ib_sync_interval.value())        self.settings.setValue("ib_sync_lookback", self.ib_sync_lookback.value())    # ---------------- Actions ----------------    def pick_config(self):        start_dir = str((self.APP_DIR / "config").resolve())        path, _ = QtWidgets.QFileDialog.getOpenFileName(            self, "Select config file", start_dir, "TOML files (*.toml);;All files (*.*)"        )        if path:            self.cfg_edit.setText(path)            self.persist_settings()    def start_service(self):        try:            self.persist_settings()            self._stopping = False            cfg = self.cfg_path()            if not cfg.exists():                QtWidgets.QMessageBox.critical(self, "Config not found", f"Config file does not exist:\n{cfg}")                return            if self.proc.state() != QtCore.QProcess.NotRunning:                QtWidgets.QMessageBox.information(self, "Already running", "Service process is already running.")                return            env = QtCore.QProcessEnvironment.systemEnvironment()            env.insert("QT_PLUGIN_PATH", "")            env.insert("QT_QPA_PLATFORM_PLUGIN_PATH", "")            env.insert("SENSEI_MODE", self.mode_combo.currentText())            db_path = self.db_edit.text().strip()            if db_path:                env.insert("SENSEI_DB_PATH", db_path)            if self.signals_enable.isChecked():                env.insert("SENSEI_SIGNALS_ENABLE", "1")                env.insert("SENSEI_SIGNALS_PATH", self.signals_path.text().strip() or "signals")            else:                env.insert("SENSEI_SIGNALS_ENABLE", "0")            if self.ib_sync_enable.isChecked():                env.insert("SENSEI_IB_SYNC_ENABLE", "1")                env.insert("SENSEI_IB_SYNC_INTERVAL_SECONDS", str(self.ib_sync_interval.value()))                env.insert("SENSEI_IB_SYNC_LOOKBACK_MINUTES", str(self.ib_sync_lookback.value()))            else:                env.insert("SENSEI_IB_SYNC_ENABLE", "0")            self.proc.setProcessEnvironment(env)            self.proc.setWorkingDirectory(str(self.APP_DIR))            py = sys.executable            args = ["-u", "-m", "app.service", "--config", str(cfg)]            self.append_log(f"[runner] Start: {py} {' '.join(args)}")            self.gui_log(f"[runner] Start: {py} {' '.join(args)}")            self.proc.start(py, args)            self.btn_start.setEnabled(False)            self.btn_stop.setEnabled(True)            self.set_status("starting...")            self._heartbeat_timer.start()        except Exception:            tb = traceback.format_exc()            self._write_crash(tb)            self.append_log("[gui] start error")            QtWidgets.QMessageBox.critical(self, "Start error", tb)    def stop_service(self):        if self.proc.state() == QtCore.QProcess.NotRunning:            self.append_log("[runner] Stop: not running.")            self.gui_log("[runner] Stop: not running.")            return        self._stopping = True        self.append_log("[runner] Stop: terminating service...")        self.gui_log("[runner] Stop: terminating service...")        self.proc.terminate()        self._stop_timer.start(3000)        self.set_status("stopping...")    def force_kill(self):        if self.proc.state() != QtCore.QProcess.NotRunning:            self.append_log("[runner] Stop: kill...")            self.gui_log("[runner] Stop: kill...")            self.proc.kill()    # ---------------- QProcess callbacks ----------------    def on_proc_started(self):        self.set_status("running")        self.append_log("[runner] Ready.")        self.gui_log("[runner] Ready.")    def on_proc_finished(self, exit_code: int, exit_status: QtCore.QProcess.ExitStatus):        self._stop_timer.stop()        self._heartbeat_timer.stop()        self.append_log(f"[runner] Service finished. exitCode={exit_code} exitStatus={int(exit_status)}")        self.gui_log(f"[runner] Service finished. exitCode={exit_code} exitStatus={int(exit_status)}")        self.btn_start.setEnabled(True)        self.btn_stop.setEnabled(False)        self.set_status("idle")        # Если пользователь запросил Exit — после остановки сервиса завершаемся.        if self._exit_requested:            QtWidgets.QApplication.instance().quit()    def on_proc_error(self, err: QtCore.QProcess.ProcessError):        name = qprocess_err_name(err)        # err=1 (Crashed) при kill — ожидаемо. Не маркируем как критическую ошибку.        if self._stopping and err == QtCore.QProcess.Crashed:            self.append_log(f"[runner] Process state: {name} (expected on kill)")            self.gui_log(f"[runner] Process state: {name} (expected on kill)")            return        self.append_log(f"[runner] Process error: {name}")        self.gui_log(f"[runner] Process error: {name}")    def on_ready_read(self):        try:            data = bytes(self.proc.readAllStandardOutput())            if not data:                return            text = data.decode("utf-8", errors="replace").rstrip("\n")            if text:                for line in text.splitlines():                    self.append_log(line)        except Exception as e:            self.append_log(f"[gui] read error: {e}")    # ---------------- Heartbeat ----------------    def poll_heartbeat(self):        # Если таблицы heartbeat нет — пропуск.        try:            db_path = self.db_edit.text().strip()            if not db_path:                return            dbp = Path(db_path)            if not dbp.is_absolute():                dbp = (self.APP_DIR / dbp).resolve()            if not dbp.exists():                return            con = sqlite3.connect(str(dbp))            cur = con.cursor()            cur.execute("SELECT ts_utc FROM heartbeat WHERE name='service' ORDER BY ts_utc DESC LIMIT 1")            row = cur.fetchone()            con.close()            if row and row[0]:                self.set_status(f"running (hb={row[0]})")        except Exception:            return    # ---------------- Window lifecycle ----------------    def showEvent(self, event: QtGui.QShowEvent):        try:            self.gui_log(f"[qt] showEvent visible={self.isVisible()} minimized={self.isMinimized()}")        except Exception:            pass        super().showEvent(event)    def hideEvent(self, event: QtGui.QHideEvent):        try:            self.gui_log(f"[qt] hideEvent visible={self.isVisible()}")        except Exception:            pass        super().hideEvent(event)    def closeEvent(self, event):        self._log("[qt] closeEvent: exiting (no tray mode)")        try:            self._stop_service_blocking()   # terminate -> wait -> kill -> wait        finally:            event.accept()        self.append_log(f"[qt] closeEvent received (exit_requested={self._exit_requested})")        self.gui_log(f"[qt] closeEvent received (exit_requested={self._exit_requested})")        self.gui_log(f"closeEvent: spontaneous={sp} proc_state={int(self.proc.state())}")        if not self._exit_requested:            event.ignore()            self._tray_hide()            return        # exit_requested=True -> действительно выходим.        if self.proc.state() == QtCore.QProcess.NotRunning:            event.accept()            return        # Сервис запущен: сначала останавливаем, потом выйдем в on_proc_finished()        event.ignore()        self.append_log("[runner] Close requested: stopping service...")        self.gui_log("[runner] Close requested: stopping service...")        try:            self.stop_service()        except Exception:            try:                self.proc.kill()            except Exception:                pass        QtCore.QTimer.singleShot(5000, self._force_exit_timeout)    def _force_exit_timeout(self):        if self.proc.state() != QtCore.QProcess.NotRunning:            self.append_log("[runner] Exit timeout: kill...")            self.gui_log("[runner] Exit timeout: kill...")            try:                self.proc.kill()            except Exception:                pass        QtWidgets.QApplication.instance().quit()def main():    try:        # Важно: не хранить windows-пути в строках вида "C:\Users\..." без raw-строк.        app = QtWidgets.QApplication(sys.argv)        # КРИТИЧНО: не завершать приложение при закрытии/скрытии окна        try:            app.setQuitOnLastWindowClosed(False)        except Exception:            pass        exit_log = logs_dir() / "qt_runner_exit.txt"        def _write_exit_line(line: str) -> None:            try:                with exit_log.open("a", encoding="utf-8", errors="replace") as f:                    f.write(line + "\n")            except Exception:                pass        app.aboutToQuit.connect(lambda: _write_exit_line(f"aboutToQuit ts_local={time.strftime('%Y-%m-%d %H:%M:%S')}"))        app.lastWindowClosed.connect(lambda: _write_exit_line(f"lastWindowClosed ts_local={time.strftime('%Y-%m-%d %H:%M:%S')}"))        w = RunnerWindow()        w.destroyed.connect(lambda: _write_exit_line(f"window_destroyed ts_local={time.strftime('%Y-%m-%d %H:%M:%S')}"))        w.show()        _write_exit_line(f"exec_enter ts_local={time.strftime('%Y-%m-%d %H:%M:%S')}")        rc = app.exec_()        _write_exit_line(f"exec_return rc={rc} ts_local={time.strftime('%Y-%m-%d %H:%M:%S')}")        return rc    except BaseException:        tb = traceback.format_exc()        write_text_safe(logs_dir() / "qt_runner_crash.txt", tb)        raiseif __name__ == "__main__":    raise SystemExit(main())